{
  "case_id": "C07",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "About one in three people with major depression don't get better on the first antidepressant they're prescribed. What if a routine blood test could flag that in advance?",
      "on_screen": "Title card: 'Can a blood test predict who responds to an antidepressant?' Ten person icons; three fade out.",
      "claim_refs": ["SYN-C07:Background — roughly one third do not respond to a first-line SSRI"]
    },
    {
      "beat": "What was measured",
      "narration": "Researchers followed 512 adults starting an SSRI. At the outset they took one blood sample and measured interleukin-6, a marker of inflammation. Twelve weeks later, among those with the lowest IL-6, 58 percent had responded. Among those with the highest, only 34 percent had.",
      "on_screen": "Cohort of 512 splits into three tertiles by IL-6; bar chart shows 58% lowest tertile vs 34% highest tertile at 12 weeks.",
      "claim_refs": ["SYN-C07:Abstract — 512 adults, response at 12 weeks", "SYN-C07:Results — 34% highest tertile, 58% lowest tertile", "SYN-C07:Methods — single baseline high-sensitivity IL-6; response = 50% HAM-D reduction"]
    },
    {
      "beat": "How solid is the link",
      "narration": "That gap held up after accounting for age, sex, body-mass index, smoking, and how severe the depression was to begin with. High inflammation was tied to roughly sixty percent lower odds of responding.",
      "on_screen": "Adjusted odds ratio 0.41, 95% confidence interval 0.27 to 0.63, with the list of adjustment variables beside it.",
      "claim_refs": ["SYN-C07:Abstract — adjusted odds ratio 0.41 (0.27-0.63)", "SYN-C07:Statistical analysis — adjusted for age, sex, baseline HAM-D, BMI, smoking"]
    },
    {
      "beat": "The proposed explanation",
      "narration": "Why might inflammation matter? The team's proposal is that it diverts tryptophan, the raw material for serotonin, down a different route called the kynurenine pathway, leaving less serotonin for the brain. But that is a hypothesis. They never measured any kynurenine chemicals, and they never changed anyone's IL-6 to see what happened.",
      "on_screen": "Animated diagram of tryptophan branching to serotonin or kynurenine, stamped 'PROPOSED — NOT MEASURED'. Caption: 'Kynurenine metabolites measured: none'.",
      "claim_refs": ["SYN-C07:Abstract — proposed kynurenine shunt mechanism", "SYN-C07:Methods — no metabolite panel run; IL-6 not manipulated", "SYN-C07:Results — kynurenine metabolites measured: none", "SYN-C07:Study design — proposed, untested mechanism"]
    },
    {
      "beat": "Bottom line",
      "narration": "So this is an association, not a proven cause. It's an observational study built on one blood measurement. IL-6 looks like a promising signpost for who might need a different treatment first, but it isn't a test yet, and the explanation behind it is still untested.",
      "on_screen": "Two-column summary: 'Shown — higher baseline IL-6 tracks with lower SSRI response' / 'Not shown — that inflammation causes it, or how'.",
      "claim_refs": ["SYN-C07:Limitations — observational cohort; single baseline IL-6 measurement", "SYN-C07:Conclusion — association reported, mechanism proposed", "SYN-C07:Discussion — candidate stratification marker"]
    }
  ]
}
